// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Governor} from "@openzeppelin/contracts/governance/Governor.sol";
import {GovernorSettings} from "@openzeppelin/contracts/governance/extensions/GovernorSettings.sol";
import {GovernorCountingSimple} from "@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol";
import {GovernorVotes} from "@openzeppelin/contracts/governance/extensions/GovernorVotes.sol";
import {GovernorVotesQuorumFraction} from "@openzeppelin/contracts/governance/extensions/GovernorVotesQuorumFraction.sol";
import {GovernorTimelockControl} from "@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol";
import {TimelockController} from "@openzeppelin/contracts/governance/TimelockController.sol";
import {IVotes} from "@openzeppelin/contracts/governance/utils/IVotes.sol";

/// @dev Post-quantum signature verifier (e.g. ZKNOX Dilithium). Same shape as ZKNOX_ethdilithium.verify.
interface IPQVerifier {
    function verify(bytes calldata pk, bytes calldata m, bytes calldata sig, string calldata aux) external view returns (bool);
}

/**
 * @title GovernancePlugin
 * @notice Binding, token-weighted governance for the UtP DAO.
 * @dev Built on OpenZeppelin Governor (audited):
 *      - For / Against / Abstain counting (GovernorCountingSimple)
 *      - Voting delay, voting period, proposal threshold (GovernorSettings)
 *      - Vote weight and quorum from UTP ERC20Votes snapshots (GovernorVotes, GovernorVotesQuorumFraction)
 *      - Successful proposals are queued and executed ONLY through the timelock (GovernorTimelockControl)
 *
 *      Optional post-quantum hybrid mode (off by default, see roadmap decision D1):
 *      when `requireHybridAuth` is true, every vote must carry a PQ signature in `params`
 *      (abi.encode(bytes pqPublicKey, bytes pqSignature)) over `hybridVoteDigest(...)`.
 *      Enforced in `_castVote`, so castVote / castVoteBySig cannot bypass it (no downgrade).
 */
contract GovernancePlugin is
    Governor,
    GovernorSettings,
    GovernorCountingSimple,
    GovernorVotes,
    GovernorVotesQuorumFraction,
    GovernorTimelockControl
{
    /// @notice PQ verifier used when hybrid auth is required. Zero when hybrid mode is off.
    IPQVerifier public immutable pqVerifier;

    /// @notice When true, every vote must include a valid PQ signature.
    bool public immutable requireHybridAuth;

    error HybridAuthRequired();
    error InvalidHybridAuth();
    error HybridVerifierMissing();

    struct Config {
        uint48 votingDelay; // blocks between proposal and vote start
        uint32 votingPeriod; // blocks the vote stays open
        uint256 proposalThreshold; // min UTP votes to propose
        uint256 quorumPercent; // % of past total supply (0-100)
    }

    constructor(
        IVotes token,
        TimelockController timelock,
        Config memory cfg,
        address pqVerifier_,
        bool requireHybridAuth_
    )
        Governor("UtP Governance")
        GovernorSettings(cfg.votingDelay, cfg.votingPeriod, cfg.proposalThreshold)
        GovernorVotes(token)
        GovernorVotesQuorumFraction(cfg.quorumPercent)
        GovernorTimelockControl(timelock)
    {
        if (requireHybridAuth_ && pqVerifier_ == address(0)) revert HybridVerifierMissing();
        pqVerifier = IPQVerifier(pqVerifier_);
        requireHybridAuth = requireHybridAuth_;
    }

    // ------------------------------------------------------------------
    // Hybrid (post-quantum) voting
    // ------------------------------------------------------------------

    /// @notice Message a voter signs with their PQ key. Binds proposal, voter, choice, contract and chain (replay protection).
    function hybridVoteDigest(uint256 proposalId, address voter, uint8 support) public view returns (bytes32) {
        return keccak256(abi.encodePacked(proposalId, voter, support, address(this), block.chainid));
    }

    /// @notice Convenience wrapper: vote with a PQ signature.
    function castVoteHybrid(
        uint256 proposalId,
        uint8 support,
        bytes calldata pqPublicKey,
        bytes calldata pqSignature
    ) external returns (uint256) {
        return _castVote(proposalId, _msgSender(), support, "", abi.encode(pqPublicKey, pqSignature));
    }

    function _castVote(
        uint256 proposalId,
        address account,
        uint8 support,
        string memory reason,
        bytes memory params
    ) internal override returns (uint256) {
        if (requireHybridAuth) {
            if (params.length == 0) revert HybridAuthRequired();
            (bytes memory pk, bytes memory sig) = abi.decode(params, (bytes, bytes));
            bytes32 digest = hybridVoteDigest(proposalId, account, support);
            if (sig.length == 0 || !pqVerifier.verify(pk, abi.encodePacked(digest), sig, "")) {
                revert InvalidHybridAuth();
            }
        }
        return super._castVote(proposalId, account, support, reason, params);
    }

    // ------------------------------------------------------------------
    // Required overrides
    // ------------------------------------------------------------------

    function votingDelay() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingDelay();
    }

    function votingPeriod() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingPeriod();
    }

    function proposalThreshold() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.proposalThreshold();
    }

    function quorum(uint256 blockNumber) public view override(Governor, GovernorVotesQuorumFraction) returns (uint256) {
        return super.quorum(blockNumber);
    }

    function state(uint256 proposalId) public view override(Governor, GovernorTimelockControl) returns (ProposalState) {
        return super.state(proposalId);
    }

    function proposalNeedsQueuing(uint256 proposalId) public view override(Governor, GovernorTimelockControl) returns (bool) {
        return super.proposalNeedsQueuing(proposalId);
    }

    function _queueOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint48) {
        return super._queueOperations(proposalId, targets, values, calldatas, descriptionHash);
    }

    function _executeOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) {
        super._executeOperations(proposalId, targets, values, calldatas, descriptionHash);
    }

    function _cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint256) {
        return super._cancel(targets, values, calldatas, descriptionHash);
    }

    function _executor() internal view override(Governor, GovernorTimelockControl) returns (address) {
        return super._executor();
    }
}

/**
 * Governance-core deployment, shared by scripts/deploy.cjs and the test suite
 * so tests exercise exactly the wiring that ships.
 *
 * Deploys: DAO, UTPToken, UtPTimelock, GovernancePlugin, Treasury, PluginRegistry.
 * Final permission state (verified by verifyCore):
 *   - Timelock holds ROOT on the DAO and is the only executor of DAO actions.
 *   - GovernancePlugin is the timelock's only proposer (+ canceller); it holds no DAO permissions.
 *   - Timelock administers itself (no external admin).
 *   - Deployer holds no ROOT and no timelock admin.
 *   - Optional guardian may CANCEL queued operations (emergency veto), nothing else.
 *   - PluginRegistry holds only UNINSTALL_PLUGIN_PERMISSION.
 */

const ZERO = "0x0000000000000000000000000000000000000000";

function log(logger, msg) {
  if (logger) logger(msg);
}

async function deployCore(ethers, deployer, params, logger) {
  const p = {
    initialHolder: deployer.address,
    initialSupply: ethers.parseEther("10000000"),
    votingDelay: 1,
    votingPeriod: 50,
    proposalThreshold: 0n,
    quorumPercent: 4,
    timelockMinDelay: 3600,
    guardian: ZERO,
    pqVerifier: ZERO,
    requireHybridAuth: false,
    ...params,
  };

  const deployed = {};
  const deploy = async (name, args) => {
    const F = await ethers.getContractFactory(name, deployer);
    const c = await F.deploy(...args);
    await c.waitForDeployment();
    const addr = await c.getAddress();
    const rcpt = await c.deploymentTransaction().wait();
    deployed[name] = addr;
    log(logger, `  ${name.padEnd(17)} ${addr}  (gas ${rcpt.gasUsed})`);
    return c;
  };
  const send = async (label, txPromise) => {
    const tx = await txPromise;
    const rcpt = await tx.wait();
    log(logger, `  ✔ ${label}  (gas ${rcpt.gasUsed})`);
    return rcpt;
  };

  log(logger, "Deploying contracts");
  const dao = await deploy("DAO", []);
  const daoAddr = await dao.getAddress();
  const token = await deploy("UTPToken", [daoAddr, p.initialHolder, p.initialSupply]);
  // admin = deployer only during setup; renounced below
  const timelock = await deploy("UtPTimelock", [p.timelockMinDelay, [], [ZERO], deployer.address]);
  const governance = await deploy("GovernancePlugin", [
    await token.getAddress(),
    await timelock.getAddress(),
    {
      votingDelay: p.votingDelay,
      votingPeriod: p.votingPeriod,
      proposalThreshold: p.proposalThreshold,
      quorumPercent: p.quorumPercent,
    },
    p.pqVerifier,
    p.requireHybridAuth,
  ]);
  const treasury = await deploy("Treasury", [daoAddr]);
  const registry = await deploy("PluginRegistry", [daoAddr]);

  const tlAddr = await timelock.getAddress();
  const govAddr = await governance.getAddress();
  const PROPOSER = await timelock.PROPOSER_ROLE();
  const CANCELLER = await timelock.CANCELLER_ROLE();
  const TL_ADMIN = await timelock.DEFAULT_ADMIN_ROLE();
  const ROOT = await dao.ROOT_PERMISSION_ID();
  const UNINSTALL = await dao.UNINSTALL_PLUGIN_PERMISSION_ID();

  log(logger, "Wiring permissions");
  await send("timelock: governance = proposer", timelock.grantRole(PROPOSER, govAddr));
  await send("timelock: governance = canceller", timelock.grantRole(CANCELLER, govAddr));
  if (p.guardian !== ZERO) {
    await send(`timelock: guardian ${p.guardian} = canceller`, timelock.grantRole(CANCELLER, p.guardian));
  }
  await send("dao: timelock = ROOT", dao.grant(daoAddr, tlAddr, ROOT));
  await send("dao: registry = UNINSTALL_PLUGIN", dao.grant(daoAddr, await registry.getAddress(), UNINSTALL));
  await send("registry: install governance plugin", registry.installPlugin(govAddr));

  log(logger, "Removing deployer privileges");
  await send("dao: revoke deployer ROOT", dao.revoke(daoAddr, deployer.address, ROOT));
  await send("timelock: deployer renounces admin", timelock.renounceRole(TL_ADMIN, deployer.address));

  return {
    addresses: deployed,
    params: p,
    contracts: { dao, token, timelock, governance, treasury, registry },
  };
}

/** Asserts the post-deploy permission invariants. Throws on any violation. */
async function verifyCore(core, deployerAddress, logger) {
  const { dao, timelock, governance, registry } = core.contracts;
  const daoAddr = await dao.getAddress();
  const tlAddr = await timelock.getAddress();
  const govAddr = await governance.getAddress();
  const regAddr = await registry.getAddress();
  const ROOT = await dao.ROOT_PERMISSION_ID();
  const EXEC = await dao.EXECUTE_PERMISSION_ID();
  const TL_ADMIN = await timelock.DEFAULT_ADMIN_ROLE();

  const checks = [
    ["timelock holds DAO ROOT", await dao.hasPermission(daoAddr, tlAddr, ROOT), true],
    ["deployer has no DAO ROOT", await dao.hasPermission(daoAddr, deployerAddress, ROOT), false],
    ["deployer cannot execute on DAO", await dao.hasPermission(daoAddr, deployerAddress, EXEC), false],
    ["governance cannot execute on DAO directly", await dao.hasPermission(daoAddr, govAddr, EXEC), false],
    ["registry has no DAO ROOT", await dao.hasPermission(daoAddr, regAddr, ROOT), false],
    ["timelock is self-administered", await timelock.hasRole(TL_ADMIN, tlAddr), true],
    ["deployer has no timelock admin", await timelock.hasRole(TL_ADMIN, deployerAddress), false],
    ["governance is timelock proposer", await timelock.hasRole(await timelock.PROPOSER_ROLE(), govAddr), true],
    ["deployer is not timelock proposer", await timelock.hasRole(await timelock.PROPOSER_ROLE(), deployerAddress), false],
    ["governance points at timelock", (await governance.timelock()).toLowerCase(), tlAddr.toLowerCase()],
    ["governance plugin installed", (await registry.plugins(govAddr)).active, true],
  ];

  let failed = 0;
  for (const [label, actual, expected] of checks) {
    const ok = actual === expected;
    if (!ok) failed++;
    log(logger, `  ${ok ? "✔" : "✘"} ${label}${ok ? "" : ` (got ${actual}, want ${expected})`}`);
  }
  if (failed) throw new Error(`${failed} post-deploy invariant(s) failed`);
  return checks.length;
}

module.exports = { deployCore, verifyCore, ZERO };

/**
 * Post-deploy smoke test against a live RPC, using deployments/<network>.json.
 *
 *   npx hardhat run scripts/smoke-governance.cjs --network localhost    # full lifecycle (time travel)
 *   npx hardhat run scripts/smoke-governance.cjs --network rskTestnet   # read-only invariant checks
 *
 * Local: delegate -> propose -> vote -> queue -> wait -> execute a real proposal.
 * Remote: re-verify every permission invariant and print live governance settings.
 */
const hre = require("hardhat");
const fs = require("fs");
const path = require("path");
const { verifyCore } = require("./lib/deploy-core.cjs");

const LOCAL = new Set(["hardhat", "localhost"]);

async function main() {
  const network = hre.network.name;
  const file = path.join(__dirname, "..", "deployments", `${network}.json`);
  if (!fs.existsSync(file)) throw new Error(`No ${path.relative(process.cwd(), file)}; deploy first.`);
  const dep = JSON.parse(fs.readFileSync(file, "utf8"));
  const A = dep.contracts;
  const { ethers } = hre;

  const at = (name, addr) => ethers.getContractAt(name, addr);
  const contracts = {
    dao: await at("DAO", A.DAO),
    token: await at("UTPToken", A.UTPToken),
    timelock: await at("UtPTimelock", A.UtPTimelock),
    governance: await at("GovernancePlugin", A.GovernancePlugin),
    treasury: await at("Treasury", A.Treasury),
    registry: await at("PluginRegistry", A.PluginRegistry),
  };
  const g = contracts.governance;

  console.log(`=== Smoke test: ${network} (chainId ${(await ethers.provider.getNetwork()).chainId}) ===`);
  for (const [k, v] of Object.entries(A)) {
    const code = await ethers.provider.getCode(v);
    if (code === "0x") throw new Error(`${k} at ${v} has no code`);
    console.log(`  ✔ ${k.padEnd(17)} ${v} (${(code.length - 2) / 2} bytes)`);
  }
  console.log("Invariants");
  await verifyCore({ contracts }, dep.deployer, console.log);
  console.log("Live settings");
  const clock = await g.clock();
  console.log(`  votingDelay=${await g.votingDelay()} votingPeriod=${await g.votingPeriod()} threshold=${ethers.formatEther(await g.proposalThreshold())} UTP`);
  console.log(`  quorum now=${ethers.formatEther(await g.quorum(clock - 1n))} UTP  timelockDelay=${await contracts.timelock.getMinDelay()}s  hybrid=${await g.requireHybridAuth()}`);

  if (!LOCAL.has(network)) {
    console.log("=== SMOKE OK (read-only on remote network) ===");
    return;
  }

  // ---- Full lifecycle on a local node ----
  const [deployer, voter, recipient] = await ethers.getSigners();
  const mine = async (n) => { for (let i = 0; i < n; i++) await ethers.provider.send("evm_mine", []); };
  const step = (m) => console.log(`  → ${m}`);

  console.log("Lifecycle");
  step("distribute + delegate 1,000,000 UTP to voter");
  await (await contracts.token.connect(deployer).transfer(voter.address, ethers.parseEther("1000000"))).wait();
  await (await contracts.token.connect(voter).delegate(voter.address)).wait();
  await mine(1);

  step("fund treasury with 1 ETH");
  await (await deployer.sendTransaction({ to: A.Treasury, value: ethers.parseEther("1") })).wait();

  const withdraw = contracts.treasury.interface.encodeFunctionData("withdraw", [recipient.address, ethers.parseEther("0.25")]);
  const daoCall = contracts.dao.interface.encodeFunctionData("execute", [[A.Treasury], [0], [withdraw]]);
  const targets = [A.DAO], values = [0], calldatas = [daoCall];
  const description = `Smoke test payout ${Date.now()}`;
  const descHash = ethers.id(description);

  step("propose treasury payout");
  await (await g.connect(voter).propose(targets, values, calldatas, description)).wait();
  const id = await g.hashProposal(targets, values, calldatas, descHash);
  const stateName = async () => ["Pending", "Active", "Canceled", "Defeated", "Succeeded", "Queued", "Expired", "Executed"][Number(await g.state(id))];
  console.log(`    proposal ${id.toString().slice(0, 12)}… state=${await stateName()}`);

  await mine(Number(await g.votingDelay()) + 1);
  step(`vote FOR (state=${await stateName()})`);
  await (await g.connect(voter).castVote(id, 1)).wait();

  await mine(Number(await g.votingPeriod()));
  step(`queue (state=${await stateName()})`);
  await (await g.queue(targets, values, calldatas, descHash)).wait();

  const delay = Number(await contracts.timelock.getMinDelay());
  step(`wait timelock ${delay}s (state=${await stateName()})`);
  await ethers.provider.send("evm_increaseTime", [delay]);
  await mine(1);

  const before = await ethers.provider.getBalance(recipient.address);
  step("execute");
  await (await g.execute(targets, values, calldatas, descHash)).wait();
  const delta = (await ethers.provider.getBalance(recipient.address)) - before;
  console.log(`    state=${await stateName()}  recipient +${ethers.formatEther(delta)} ETH`);
  if (delta !== ethers.parseEther("0.25")) throw new Error("Payout amount mismatch");
  console.log("=== SMOKE OK (full lifecycle) ===");
}

main().catch((e) => { console.error(`=== SMOKE FAILED === ${e.message}`); process.exitCode = 1; });

/**
 * Governance parameters per network (roadmap decision D2).
 * RSK blocks average ~30s: 2880 blocks ≈ 1 day.
 * Change these, not the deploy script.
 */
const { ethers } = require("ethers");

const ZERO = "0x0000000000000000000000000000000000000000";

module.exports = {
  hardhat: {
    chainId: 31337,
    initialSupply: ethers.parseEther("10000000"),
    votingDelay: 1,
    votingPeriod: 20,
    proposalThreshold: ethers.parseEther("1000"),
    quorumPercent: 4,
    timelockMinDelay: 60,
    guardian: ZERO,
    minDeployerBalance: 0n,
  },
  localhost: {
    chainId: 31337,
    initialSupply: ethers.parseEther("10000000"),
    votingDelay: 1,
    votingPeriod: 20,
    proposalThreshold: ethers.parseEther("1000"),
    quorumPercent: 4,
    timelockMinDelay: 60,
    guardian: ZERO,
    minDeployerBalance: 0n,
  },
  rskTestnet: {
    chainId: 31,
    initialSupply: ethers.parseEther("10000000"), // 10M UTP to deployer for tester distribution
    votingDelay: 1, // ~30s
    votingPeriod: 2880, // ~1 day
    proposalThreshold: ethers.parseEther("10000"), // 0.1% of initial supply
    quorumPercent: 4,
    timelockMinDelay: 3600, // 1 hour
    guardian: process.env.GUARDIAN_ADDRESS || ZERO, // optional emergency canceller (multisig recommended)
    minDeployerBalance: ethers.parseEther("0.01"), // tRBTC for gas
  },
  // rskMainnet intentionally absent: blocked until Phase 3 (audit) passes.
};

/**
 * Deploy the UtP governance core.
 *
 *   npx hardhat run scripts/deploy.cjs --network hardhat      # in-process rehearsal
 *   npx hardhat run scripts/deploy.cjs --network localhost    # against `npx hardhat node`
 *   npx hardhat run scripts/deploy.cjs --network rskTestnet   # needs DEPLOYER_PRIVATE_KEY
 *
 * Outputs:
 *   deployments/<network>.json            canonical addresses (read by the app)
 *   deployments/logs/<network>-<ts>.log   full transcript of this run
 *
 * Financial modules (StablecoinController, UBTC, EventMarket) are NOT deployed here;
 * they stay gated until Roadmap Phase 4.
 */
const hre = require("hardhat");
const fs = require("fs");
const path = require("path");
const { deployCore, verifyCore } = require("./lib/deploy-core.cjs");
const config = require("./deploy.config.cjs");

const LOCAL = new Set(["hardhat", "localhost"]);

async function main() {
  const network = hre.network.name;
  const ts = new Date().toISOString().replace(/[:.]/g, "-");
  const logDir = path.join(__dirname, "..", "deployments", "logs");
  fs.mkdirSync(logDir, { recursive: true });
  const logFile = path.join(logDir, `${network}-${ts}.log`);
  const lines = [];
  const log = (m) => { console.log(m); lines.push(m); };
  const flush = () => fs.writeFileSync(logFile, lines.join("\n") + "\n");

  try {
    const params = config[network];
    if (!params) {
      throw new Error(`No deploy config for network "${network}". Mainnet is blocked until the Phase 3 audit gate.`);
    }

    const [deployer] = await hre.ethers.getSigners();
    if (!deployer) throw new Error("No deployer account. Set DEPLOYER_PRIVATE_KEY for non-local networks.");

    // ---- Preflight ----
    const net = await hre.ethers.provider.getNetwork();
    const balance = await hre.ethers.provider.getBalance(deployer.address);
    log("=== UtP governance core deployment ===");
    log(`network   ${network} (chainId ${net.chainId})`);
    log(`deployer  ${deployer.address}`);
    log(`balance   ${hre.ethers.formatEther(balance)} native`);
    log(`block     ${await hre.ethers.provider.getBlockNumber()}`);
    log(`params    votingDelay=${params.votingDelay} votingPeriod=${params.votingPeriod} threshold=${hre.ethers.formatEther(params.proposalThreshold)} UTP quorum=${params.quorumPercent}% timelock=${params.timelockMinDelay}s guardian=${params.guardian}`);

    if (BigInt(net.chainId) !== BigInt(params.chainId)) {
      throw new Error(`chainId mismatch: RPC reports ${net.chainId}, config expects ${params.chainId}`);
    }
    if (balance < params.minDeployerBalance) {
      throw new Error(`Deployer balance ${hre.ethers.formatEther(balance)} below minimum ${hre.ethers.formatEther(params.minDeployerBalance)}. Fund it from a testnet faucet.`);
    }
    if (!LOCAL.has(network) && (params.pqVerifier || params.requireHybridAuth)) {
      throw new Error("Hybrid PQ voting has no production verifier yet (decision D1). Refusing to deploy with mocks.");
    }

    // ---- Deploy + wire ----
    const started = Date.now();
    const core = await deployCore(hre.ethers, deployer, params, log);

    // ---- Verify invariants ----
    log("Verifying post-deploy invariants");
    const n = await verifyCore(core, deployer.address, log);
    log(`All ${n} invariants hold. Took ${((Date.now() - started) / 1000).toFixed(1)}s.`);

    // ---- Persist ----
    const out = {
      network,
      chainId: Number(net.chainId),
      deployer: deployer.address,
      deployedAt: new Date().toISOString(),
      blockNumber: await hre.ethers.provider.getBlockNumber(),
      params: Object.fromEntries(Object.entries(params).map(([k, v]) => [k, typeof v === "bigint" ? v.toString() : v])),
      contracts: core.addresses,
    };
    if (network !== "hardhat") {
      const file = path.join(__dirname, "..", "deployments", `${network}.json`);
      fs.writeFileSync(file, JSON.stringify(out, null, 2) + "\n");
      log(`Wrote ${path.relative(process.cwd(), file)}`);
    }
    log(`Log: ${path.relative(process.cwd(), logFile)}`);
    log("=== DEPLOYMENT OK ===");
  } catch (err) {
    log(`=== DEPLOYMENT FAILED === ${err.message}`);
    flush();
    throw err;
  }
  flush();
}

main().catch(() => { process.exitCode = 1; });

